// `pnpm clients`: generates the Kit clients in src/generated from the pinned IDLs in idl/ (spec 5.1), one folder per
// program. Meteora's IDLs come from its SDKs (`pnpm --filter @top-pad/meteora idls`); our programs' come from
// `pnpm programs`, which copies target/idl/<program>.json here (the Fair Open program's joins once it has
// instructions). Never edit src/generated by hand: change the IDL and regenerate.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { rootNodeFromAnchor, type AnchorIdl } from "@codama/nodes-from-anchor";
import { renderVisitor } from "@codama/renderers-js";
import { createFromRoot } from "codama";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const programs = [
  { idl: "dbc.json", folder: "dbc" },
  { idl: "damm_v2.json", folder: "damm-v2" },
  { idl: "jupiter_lock.json", folder: "jupiter-lock" },
  { idl: "fee.json", folder: "fee" },
];

type Field = { name: string; type: unknown };
type TypeDef = { name: string; type: { kind: string; fields?: Field[] } };
type Idl = { accounts?: { name: string }[]; types?: TypeDef[] };

/** The name Codama gives a field: camelCase, leading underscores dropped. */
const codamaName = (name: string) => name.replace(/^_+/, "").replace(/_+([a-z0-9])/gi, (_, c: string) => c.toUpperCase());

/**
 * Codama's output was not clean for the DBC IDL in two ways (checked 2026-10-27 with codama 1.11.0 against
 * dynamic_bonding_curve 0.2.2), so both are fixed here, on the IDL before generation, and the byte layout is unchanged:
 * - Two fields of one struct whose names Codama makes the same (`padding_0` and `_padding_0` in
 *   MeteoraDammMigrationMetadata both become `padding0`): the later one gets a `_dup` suffix.
 * - A type that embeds an account's struct (ConfigWithTransferHook's `config: PoolConfig`): Codama turns the account's
 *   struct into the account, discriminator included, and drops the type, so the embedding struct points at a copy of
 *   the account's struct named `<Account>Data`.
 * Each fix is generic, so a later IDL with the same pattern is fixed the same way rather than failing to typecheck.
 */
function cleanForCodama(idl: Idl): Idl {
  const accounts = new Set((idl.accounts ?? []).map((a) => a.name));
  const types = idl.types ?? [];
  const copies = new Map<string, TypeDef>();
  const repoint = (t: unknown): unknown => {
    if (Array.isArray(t)) return t.map(repoint);
    if (t && typeof t === "object") {
      const node = t as Record<string, unknown>;
      const defined = node.defined as { name: string } | undefined;
      if (defined && accounts.has(defined.name)) {
        const source = types.find((x) => x.name === defined.name);
        if (source) copies.set(defined.name, { ...source, name: `${defined.name}Data` });
        return { ...node, defined: { ...defined, name: `${defined.name}Data` } };
      }
      return Object.fromEntries(Object.entries(node).map(([k, v]) => [k, repoint(v)]));
    }
    return t;
  };
  const cleaned = types.map((t) => {
    if (t.type.kind !== "struct" || !t.type.fields) return t;
    const seen = new Set<string>();
    const fields = t.type.fields.map((f) => {
      const name = seen.has(codamaName(f.name)) ? `${f.name.replace(/^_+/, "")}_dup` : f.name;
      seen.add(codamaName(name));
      return { ...f, name, type: repoint(f.type) };
    });
    return { ...t, type: { ...t.type, fields } };
  });
  return { ...idl, types: [...cleaned, ...copies.values()] };
}

for (const { idl, folder } of programs) {
  const anchorIdl = cleanForCodama(JSON.parse(readFileSync(join(root, "idl", idl), "utf8")) as Idl) as AnchorIdl;
  const codama = createFromRoot(rootNodeFromAnchor(anchorIdl));
  await codama.accept(
    renderVisitor(root, {
      generatedFolder: `src/generated/${folder}`,
      kitImportStrategy: "rootOnly",
      syncPackageJson: false,
    }),
  );
  console.log(`generated src/generated/${folder} from idl/${idl}`);
}
